mapper.select:
SELECT COUNT(*) FROM HOSPITAL_UPDATE_REQUEST
WHERE HOSPITAL_ID = #{hospitalId}
AND STATUS = 'PENDING'

mapper.delete:
DELETE FROM HOSPITAL_UPDATE_REQUEST_ANIMAL
WHERE REQUEST_ID IN( SELECT REQUEST_ID
FROM HOSPITAL_UPDATE_REQUEST
WHERE HOSPITAL_ID = #{hospitalId}
)

DELETE FROM HOSPITAL_UPDATE_REQUEST_SERVICE
WHERE REQUEST_ID IN( SELECT REQUEST_ID
FROM HOSPITAL_UPDATE_REQUEST
WHERE HOSPITAL_ID = #{hospitalId}
)

DELETE FROM HOSPITAL_UPDATE_REQUEST_MEDICAL_SUBJECT
WHERE REQUEST_ID IN( SELECT REQUEST_ID
FROM HOSPITAL_UPDATE_REQUEST
WHERE HOSPITAL_ID = #{hospitalId}
)

mapper.update:
UPDATE HOSPITAL_OWNER_REQUEST
SET HOSPITAL_ID = NULL
WHERE HOSPITAL_ID = #{hospitalId}

mapper.delete:
DELETE FROM HOSPITAL
WHERE HOSPITAL_ID = #{hospitalId}
AND STATUS='CLOSED'

mapper.select:
SELECT COUNT(DISTINCT H.HOSPITAL_ID) FROM HOSPITAL H
LEFT JOIN APP_MEMBER M ON M.MEMBER_ID = H.OWNER_ID
LEFT JOIN HOSPITAL_UPDATE_REQUEST HUR
ON HUR.HOSPITAL_ID = H.HOSPITAL_ID
AND HUR.STATUS = 'PENDING'


    AND H.STATUS != 'CLOSED'


        AND (UPPER(H.NAME) LIKE '%' || UPPER(#{keyword}) || '%'
        OR UPPER(
                NVL(
                    M.NICKNAME, NVL(H.OWNER_NAME, '')
                    )
                )
                LIKE '%' || UPPER(#{keyword}) || '%'
        )



            AND EXISTS ( SELECT 1 FROM HOSPITAL_ANIMAL HA
            WHERE HA.HOSPITAL_ID = H.HOSPITAL_ID
                AND HA.ANIMAL_ID = #{animalType}
            )



            AND HUR.REQUEST_TYPE = #{requestType}
